records=[]
def rec(title,year,typ,venue,sids=None,date=None,url=None,doi='not_found_publicly',authors='Jonathan Levy',theme='not_assessed',period='not_assessed',geog='not_assessed',level='metadata_only',note='',oa='not_found_publicly',status='verified'):
    n=len(records)+1
    refs=['P02-SL001'] if sids is None else [f'P02-SL{x:03}' for x in sids]
    refs+=['P02-SL003'] if 'Jonathan Levy' in authors else []
    records.append(dict(record_id=f'P02-L{n:03}',work_id=f'P02-LW{n:03}',edition_or_version_id=f'P02-LE{n:03}',title=title,authors=authors,person_ids=authors,type=typ,first_publication_year=str(year),edition_date=str(date or year),venue_or_publisher=venue,language='English',DOI_or_ISBN=doi,canonical_url=url or (sources[sids[0]-1]['url'] if sids else 'not_found_publicly'),open_access_url=oa,themes=theme,period_studied=period,geography_studied=geog,CHEP_relationship='relationship_unresolved' if int(year)>=2019 else 'affiliate_earlier_scholarship',affiliation_evidence='P02-SL003: Coordinator in undated accessed roster; exact appointment start not established',support_evidence='not_found_publicly',verification_status=status,source_ids=';'.join(refs),evidence_note=note or 'Bibliographic metadata attested by institutional CV; individual publisher verification remains queued.',content_basis=level,featured_on_publications_page='no'))

